// Generated by vibelang from src/advertisedEndpoint.ts; the migrate flow writes it again with each batch.
export function normalizeHttpBaseUrl(rawValue) {
    const url = new URL(rawValue);
    if (url.protocol === "ws:") {
        url.protocol = "http:";
    }
    else if (url.protocol === "wss:") {
        url.protocol = "https:";
    }
    if (url.protocol !== "http:" && url.protocol !== "https:") {
        throw new Error(`Endpoint must use HTTP or HTTPS. Received ${url.protocol}`);
    }
    url.pathname = "/";
    url.search = "";
    url.hash = "";
    return url.toString();
}
export function deriveWsBaseUrl(httpBaseUrl) {
    const url = new URL(normalizeHttpBaseUrl(httpBaseUrl));
    url.protocol = url.protocol === "https:" ? "wss:" : "ws:";
    return url.toString();
}
function classifyHostedHttpsCompatibility(httpBaseUrl, fallback = "unknown") {
    const url = new URL(normalizeHttpBaseUrl(httpBaseUrl));
    if (url.protocol === "http:") {
        return "mixed-content-blocked";
    }
    return fallback === "mixed-content-blocked" ? "unknown" : fallback;
}
export function createAdvertisedEndpoint(input) {
    const httpBaseUrl = normalizeHttpBaseUrl(input.httpBaseUrl);
    return {
        id: input.id,
        label: input.label,
        provider: input.provider,
        httpBaseUrl,
        wsBaseUrl: deriveWsBaseUrl(httpBaseUrl),
        reachability: input.reachability,
        compatibility: {
            hostedHttpsApp: input.hostedHttpsCompatibility ?? classifyHostedHttpsCompatibility(httpBaseUrl),
            desktopApp: input.desktopCompatibility ?? "compatible",
        },
        source: input.source,
        status: input.status ?? "available",
        ...(input.isDefault === undefined ? {} : { isDefault: input.isDefault }),
        ...(input.description === undefined ? {} : { description: input.description }),
    };
}
